(function(){
const {R,pick,shuffle,sample,range,plural}=H;
const ok=(c,msg)=>{if(!c)throw new Error('self-check failed: '+msg);};
const gens=[];
const G=(lvl,make,f)=>gens.push({lvl,make,star:(f||'').includes('s')||undefined,rule:(f||'').includes('r')||undefined});
function CH(q,right,wrong,o){const opts=shuffle([right,...wrong]);return Object.assign({type:'choice',q,opts,ans:opts.indexOf(right)},o||{});}
function YN(q,yes,o,labels){const opts=labels||['Да','Нет'];return Object.assign({type:'choice',q,opts,ans:yes?0:1},o||{});}
const ceil=(a,b)=>Math.ceil(a/b);
const CEIL=(a,b)=>`⌈${a} : ${b}⌉`;
/* ---------- theory helpers ---------- */
const STEPS=(t,a)=>`<div class="box ex"><b>${t}</b>${a.map((s,i)=>`<div style="margin:5px 0"><b>Шаг ${i+1}.</b> ${s}</div>`).join('')}</div>`;
const CHK=(qs)=>`<div class="box ex"><b>🤔 Проверь себя</b>${qs.map(([q,a])=>`<div style="margin:6px 0">${q}<details style="margin-top:4px"><summary style="cursor:pointer;color:var(--accent-ink);font-weight:600">Показать ответ</summary><div style="margin-top:4px">${a}</div></details></div>`).join('')}</div>`;
const REM=(r,t)=>`<div class="box tip"><b>📌 Запомни</b>${r}<div style="margin-top:6px"><i>Как запомнить:</i> ${t}</div></div>`;
const TXT='font-family:system-ui,sans-serif';

/* min number of blind picks that guarantees pred; also the worst "unlucky" pick */
function guarantee(counts,pred){let best=-1,bx=null;const x=counts.map(()=>0);
  const rec=i=>{if(i===counts.length){if(!pred(x)){const s=x.reduce((a,b)=>a+b,0);if(s>best){best=s;bx=x.slice();}}return;}for(let v=0;v<=counts[i];v++){x[i]=v;rec(i+1);}x[i]=0;};rec(0);return {n:best+1,worst:bx};}

/* ---------- SVG: cages with rabbits ---------- */
function cages(arr,o){o=o||{};const k=arr.length,cw=Math.min(64,Math.floor(310/k)),ch=o.h||96,W=k*cw+10;let s='';const mx=Math.max(...arr);
  arr.forEach((c,i)=>{const x=5+i*cw;const full=o.hlMax&&c===mx;s+=`<rect x="${x+3}" y="6" width="${cw-6}" height="${ch-30}" rx="6" fill="${full?'var(--hl)':'var(--card)'}" fill-opacity="${full?0.5:1}" stroke="var(--fig)" stroke-width="1.4"/>`;
    for(let b=1;b<4;b++)s+=`<line x1="${x+3+b*(cw-6)/4}" y1="6" x2="${x+3+b*(cw-6)/4}" y2="${ch-24}" stroke="var(--line)" stroke-width="1"/>`;
    const per=Math.max(1,Math.floor((cw-10)/14));for(let j=0;j<Math.min(c,per*3);j++){const cx=x+10+(j%per)*14,cy=ch-34-Math.floor(j/per)*14;s+=`<circle cx="${cx}" cy="${cy}" r="5.5" fill="var(--accent)" fill-opacity=".75"/>`;}
    s+=`<text x="${x+cw/2}" y="${ch-8}" text-anchor="middle" font-size="13" font-weight="700" fill="${full?'var(--accent-ink)':'var(--ink)'}">${o.labels?o.labels[i]:c}</text>`;});
  return `<svg viewBox="0 0 ${W} ${ch}" width="${W}" role="img" aria-label="Клетки с кроликами" style="${TXT}">${s}</svg>`;}
/* square split into m×m with points */
function sqPts(m,pts,side){const S=220,W=S+20;let s=`<rect x="10" y="10" width="${S}" height="${S}" fill="var(--card)" stroke="var(--fig)" stroke-width="1.6"/>`;
  for(let i=1;i<m;i++){s+=`<line x1="${10+i*S/m}" y1="10" x2="${10+i*S/m}" y2="${10+S}" stroke="var(--fig)" stroke-dasharray="4 3"/><line x1="10" y1="${10+i*S/m}" x2="${10+S}" y2="${10+i*S/m}" stroke="var(--fig)" stroke-dasharray="4 3"/>`;}
  pts.forEach(([x,y])=>{s+=`<circle cx="${10+x*S}" cy="${10+y*S}" r="4.5" fill="var(--accent)"/>`;});
  if(side)s+=`<text x="${10+S/2}" y="${S+28}" text-anchor="middle" font-size="12.5" fill="var(--ink)">${side}</text>`;
  return `<svg viewBox="0 0 ${W} ${S+(side?36:20)}" width="${W}" role="img" aria-label="Квадрат с точками" style="${TXT}">${s}</svg>`;}

/* ---------- theory ---------- */
const theory=[
{title:'Кролики и клетки',lvl:0,html:`
<p class="hook">В твоём классе 13 человек? Тогда я точно знаю: хотя бы двое из вас родились в одном месяце. Я не знаю ни одного дня рождения — но я прав всегда. Откуда такая уверенность? Это <b>принцип Дирихле</b> — самый простой и самый хитрый приём олимпиад.</p>
<div class="fig">${cages([2,1,1],{hlMax:true})}</div>
<div class="box rule"><b>Принцип Дирихле</b>Если кроликов <b>больше</b>, чем клеток, и всех кроликов рассадили по клеткам, то хотя бы в одной клетке сидят <b>не меньше двух</b> кроликов.</div>
<p><b>Почему?</b> Представь обратное: в каждой клетке не больше одного кролика. Тогда кроликов не больше, чем клеток. А их больше! Противоречие — значит, где-то сидят двое. Мы не знаем <b>где</b>, но знаем, что <b>есть</b>.</p>
<p><b>Главное умение</b> — понять, кто в задаче «кролики», а кто «клетки». Кролики — то, что раскладываем (люди, носки, числа). Клетки — то, по чему раскладываем (месяцы, цвета, остатки).</p>
${STEPS('Пример 1 (лёгкий). В классе 13 учеников. Докажи, что двое родились в одном месяце.',[
'Клетки — месяцы: их 12. Кролики — ученики: их 13.',
'13 > 12 — кроликов больше, чем клеток. Значит, в каком-то месяце родились хотя бы двое.'])}
${STEPS('Пример 2. На сервере Roblox 25 игроков, а в игре 24 разных скина. Каждый надел ровно один скин. Найдутся ли двое в одинаковых скинах?',[
'Клетки — скины (24), кролики — игроки (25).',
'25 > 24 → да, найдутся обязательно.'])}
${STEPS('Пример 3 (потруднее). В 10 коробок разложили 9 конфет. Обязательно ли есть пустая коробка?',[
'Это принцип «наоборот»: клеток больше, чем кроликов.',
'Если бы в каждой коробке была хотя бы одна конфета, конфет было бы не меньше 10. А их 9. Значит, пустая коробка <b>есть</b>.'])}
<div class="box err"><b>Частая ошибка</b>Говорить «в <b>каждой</b> клетке по два». Нет! Принцип обещает только, что найдётся <b>хотя бы одна</b> клетка с двумя кроликами. Остальные могут быть и пустыми.</div>
${CHK([['В классе 12 учеников. Обязательно ли двое родились в одном месяце?','Нет: 12 учеников могут родиться в 12 разных месяцах. Кроликов не больше, чем клеток.'],['Сколько людей нужно собрать, чтобы наверняка двое родились в один день недели?','Клеток 7 (дней недели), значит, 8 человек.']])}
${REM('Кроликов больше, чем клеток → в какой-то клетке ≥ 2 кролика.','«Не хватило клеток — кому-то придётся делиться». Сначала скажи: кто кролики, кто клетки.')}`},

{title:'«Наверняка»: самый невезучий случай',lvl:1,html:`
<p class="hook">В тёмной комнате ящик с носками: чёрные, белые и серые. Сколько носков надо вытащить не глядя, чтобы <b>наверняка</b> получилась пара одного цвета? Не «скорее всего», а <b>точно</b>.</p>
<div class="box rule"><b>Как решать задачи «наверняка»</b>1) Представь <b>самый невезучий</b> случай: вытаскиваешь как можно больше, а нужного всё нет.<br>2) Посчитай, сколько можно вытащить «неудачно».<br>3) Ответ — на <b>один больше</b>.</div>
<p><b>Почему так?</b> «Наверняка» значит «даже при самом большом невезении». Если при невезении можно вытащить 3 носка без пары, то трёх мало. А любой следующий носок уже точно даёт пару.</p>
${STEPS('Пример 1 (лёгкий). Носки трёх цветов. Сколько вытащить, чтобы наверняка была пара одного цвета?',[
'Невезучий случай: по одному носку каждого цвета — 3 носка, и пары нет.',
'4-й носок обязательно совпадёт по цвету с одним из трёх. Ответ: <b>4</b>. (Это принцип Дирихле: 4 кролика, 3 клетки-цвета.)'])}
${STEPS('Пример 2. В ящике 5 чёрных и 7 белых носков. Сколько вытащить, чтобы наверняка было <b>два чёрных</b>?',[
'Невезучий случай: сначала выходят все 7 белых, потом 1 чёрный — 8 носков, а чёрных только один.',
'Следующий носок точно чёрный. Ответ: 7 + 2 = <b>9</b>.'])}
${STEPS('Пример 3 (потруднее). В ящике 4 пары чёрных и 3 пары коричневых перчаток. Сколько вытащить не глядя, чтобы наверняка получилась пара (левая и правая одного цвета)?',[
'Невезучий случай: все 7 левых перчаток (4 чёрных + 3 коричневых). Пары нет!',
'Любая следующая — правая, к ней есть левая того же цвета. Ответ: 7 + 1 = <b>8</b>.'])}
<div class="box err"><b>Частая ошибка</b>Считать «везучий» случай: «Вытащу 2 чёрных — и готово». Задача не про удачу. «Наверняка» — всегда про самый плохой случай.</div>
${CHK([['В сундуке 6 мечей и 4 лука. Сколько предметов вынуть вслепую, чтобы наверняка был хотя бы один лук?','Невезение: все 6 мечей. Ответ: 7.'],['Носки 5 цветов. Сколько вытащить, чтобы наверняка была пара?','5 + 1 = 6.']])}
${REM('«Наверняка» = самый невезучий случай + 1.','«Представь, что тебе фатально не везёт. Сколько можно вытащить — и всё мимо? Добавь один».')}`},

{title:'Обобщённый принцип: ⌈n : k⌉',lvl:2,html:`
<p class="hook">На сервере 25 игроков разбились на 7 команд. Сколько игроков точно будет в самой большой команде? Двое? Трое? Больше? Ответ — <b>не меньше 4</b>. И это снова принцип Дирихле, только посильнее.</p>
<div class="box rule"><b>Обобщённый принцип Дирихле</b>Если n кроликов сидят в k клетках, то хотя бы в одной клетке <b>не меньше ⌈n : k⌉</b> кроликов.<br>⌈x⌉ — «округление вверх»: ⌈25 : 7⌉ = ⌈3,57…⌉ = 4; ⌈21 : 7⌉ = 3.</div>
<p><b>Почему?</b> Пусть в каждой клетке меньше, например не больше 3 кроликов. Тогда во всех 7 клетках не больше 3 · 7 = 21 кролика. А их 25 — противоречие. Значит, где-то не меньше 4.</p>
<p><b>Покрути сам:</b> рассаживай кроликов по клеткам, нажимая на клетку. Попробуй сделать так, чтобы в самой полной клетке было как можно меньше.</p>
<div class="widget" id="w-rabbits"></div>
${STEPS('Пример 1 (лёгкий). 25 игроков, 7 команд. Сколько игроков наверняка в какой-то команде?',[
'25 : 7 = 3, остаток 4. Если в каждой команде по 3, то это 21 игрок — 4 «лишних» попадут куда-то ещё.',
'⌈25 : 7⌉ = <b>4</b>. И больше гарантировать нельзя: 4, 4, 4, 4, 3, 3, 3 — максимум 4.'])}
${STEPS('Пример 2. 40 учеников написали контрольную. Больше всех ошибок — 12 — у Вовы. Докажи, что хотя бы 4 ученика сделали одинаковое число ошибок.',[
'Клетки — число ошибок: 0, 1, 2, …, 12 — это 13 клеток. Кролики — 40 учеников.',
'⌈40 : 13⌉ = ⌈3,07…⌉ = <b>4</b>. Значит, в какой-то «клетке» не меньше 4 учеников.'])}
${STEPS('Пример 3 (потруднее). В городе 1000 школьников. Найдётся ли день года, в который родились хотя бы 3 из них?',[
'Клетки — дни года. Берём худший случай: год високосный, 366 дней.',
'⌈1000 : 366⌉ = ⌈2,73…⌉ = <b>3</b>. Да, найдётся день, в который родились минимум трое.'])}
<div class="box err"><b>Частая ошибка</b>Округлять вниз: «25 : 7 ≈ 3, значит, 3». Нет: если везде по 3, поместится только 21. Остаток «выталкивает» хотя бы одного кролика выше — округляем <b>вверх</b>.</div>
${CHK([['31 конфету разложили в 10 коробок. Сколько конфет наверняка лежит в какой-то коробке?','⌈31 : 10⌉ = 4.'],['30 конфет в 10 коробок. А теперь?','⌈30 : 10⌉ = 3 (а по 3 в каждую — пример, что больше гарантировать нельзя).']])}
${REM('n кроликов, k клеток → где-то не меньше ⌈n : k⌉. Округляем ВВЕРХ.','«Разложи как можно ровнее — и посмотри на самую полную клетку».')}`},

{title:'Сколько нужно кроликов?',lvl:3,html:`
<p class="hook">В Roblox-кейсе выпадают предметы 5 редкостей. Сколько кейсов открыть, чтобы <b>наверняка</b> собрать 3 предмета одной редкости? Это обратная задача: нам нужно не «сколько в клетке», а «сколько всего кроликов».</p>
<div class="box rule"><b>Обратный принцип</b>Чтобы в одной из k клеток <b>наверняка</b> оказалось m кроликов, нужно <span class="m">k · (m − 1) + 1</span> кроликов.<br>Ровно столько: при k · (m − 1) кроликах можно посадить в каждую клетку по m − 1 — и ни в одной не будет m.</div>
<p><b>Почему?</b> Это снова «самый невезучий случай»: в каждую клетку попадает по m − 1 кролику — это k · (m − 1). Следующий кролик в любой клетке сделает m.</p>
${STEPS('Пример 1 (лёгкий). 5 редкостей, нужно 3 предмета одной редкости.',[
'Невезение: по 2 предмета каждой редкости — 5 · 2 = 10 кейсов, и трёх одинаковых нет.',
'11-й кейс обязательно даст третий предмет какой-то редкости. Ответ: 5 · 2 + 1 = <b>11</b>.'])}
${STEPS('Пример 2. Сколько учеников должно быть в школе, чтобы наверняка нашлись 4, родившиеся в одном месяце?',[
'k = 12 месяцев, m = 4. Невезение: по 3 в каждом месяце — 36 учеников.',
'Ответ: 12 · 3 + 1 = <b>37</b>.'])}
${STEPS('Пример 3 (потруднее). В ящике 3 красных, 10 синих и 10 зелёных носков. Сколько вытащить, чтобы наверняка было 4 носка одного цвета?',[
'Формула k(m − 1) + 1 = 3 · 3 + 1 = 10 — но проверим невезение честно: красных всего 3!',
'Невезение: 3 красных, 3 синих, 3 зелёных = 9 носков, четырёх одинаковых нет. Больше «неудачно» не вытащить: красные кончились.',
'Ответ: <b>10</b>. (А если бы нужно было 5 одного цвета: невезение 3 + 4 + 4 = 11, ответ 12 — красных не хватает до 4, формула тут уже не работает!)'])}
<div class="box err"><b>Частая ошибка</b>Применять формулу k(m − 1) + 1 вслепую, когда каких-то предметов мало. Всегда проверяй невезучий случай: может, какой-то цвет кончится раньше.</div>
${CHK([['Носки 4 цветов (много каждого). Сколько вытащить, чтобы наверняка было 3 одного цвета?','4 · 2 + 1 = 9.'],['50 кроликов рассадили так, что в каждой клетке не больше 6. Какое наименьшее число клеток?','⌈50 : 6⌉ = 9 клеток (в 8 клеток по 6 поместится только 48).']])}
${REM('Нужно m в одной из k клеток → k(m − 1) + 1. Но всегда проверяй невезучий случай.','«По m − 1 в каждую клетку — и ещё один сверху».')}`},

{title:'Остатки — лучшие клетки',lvl:4,html:`
<p class="hook">Загадай любые 6 целых чисел. Я гарантирую: среди них есть два, разность которых делится на 5. Например, 17, 3, 40, 28, 91, 64 → 28 − 3 = 25. Проверь на своих числах — сработает всегда!</p>
<div class="box rule"><b>Остатки</b>При делении на n бывает ровно <b>n остатков</b>: 0, 1, …, n − 1.<br>Разность двух чисел делится на n ⇔ у них <b>одинаковые остатки</b> при делении на n.<br>Поэтому среди любых <b>n + 1</b> целых чисел найдутся два, разность которых делится на n.</div>
<p><b>Почему?</b> Клетки — остатки (их n), кролики — числа (их n + 1). Два числа попадут в одну клетку — у них один остаток. А если 28 = 5 · 5 + 3 и 3 = 5 · 0 + 3, то разность 28 − 3 = 5 · 5 — остатки «сократились».</p>
${STEPS('Пример 1 (лёгкий). Числа 17, 3, 40, 28, 91, 64. Найди два с разностью, кратной 5.',[
'Остатки при делении на 5: 17 → 2, 3 → 3, 40 → 0, 28 → 3, 91 → 1, 64 → 4.',
'Совпали остатки у 3 и 28 (оба 3). Разность 28 − 3 = 25 делится на 5 ✅.'])}
${STEPS('Пример 2. Докажи, что из любых трёх целых чисел можно выбрать два с чётной суммой.',[
'Клетки — чётность: «чётные» и «нечётные», 2 клетки. Кроликов 3.',
'Два числа одной чётности найдутся. Чёт + чёт = чёт, нечёт + нечёт = чёт ✅.'])}
${STEPS('Пример 3 (потруднее). Сколько чисел нужно взять, чтобы наверняка нашлись два с разностью, кратной 7?',[
'Клеток-остатков 7: 0, 1, …, 6.',
'7 чисел могут иметь разные остатки (например, 1, 2, …, 7). А 8 чисел — уже нет. Ответ: <b>8</b>.'])}
<div class="box err"><b>Частая ошибка</b>Думать, что разность делится на n, если сами числа делятся на n. Это частный случай (остатки 0 и 0). Важно только, что остатки <b>равны</b>: 23 − 8 = 15 делится на 5, хотя ни 23, ни 8 на 5 не делятся.</div>
${CHK([['Сколько различных остатков при делении на 9?','9: от 0 до 8.'],['Обязательно ли среди 10 целых чисел есть два с разностью, кратной 10?','Нет: 0, 1, …, 9 — все остатки разные. Нужно 11 чисел.']])}
${REM('Остатков n → среди n + 1 чисел два с одинаковым остатком, их разность делится на n.','«Остатки — это клетки. Одна клетка — разность кратна n».')}`},

{title:'Принцип Дирихле в геометрии',lvl:5,html:`
<p class="hook">В квадратный ковёр 2×2 метра попало 5 капель краски. Докажи, что какие-то две капли на расстоянии не больше 1,5 метра друг от друга. Здесь «клетки» придётся нарисовать самому!</p>
<div class="box rule"><b>Геометрическая версия</b>Разбей фигуру на части (это клетки), а точки — кролики. Если точек больше, чем частей, две точки попадут в одну часть. Значит, расстояние между ними не больше «размера» части (её самого длинного отрезка).</div>
<div class="fig">${sqPts(2,[[.2,.25],[.35,.4],[.7,.2],[.3,.8],[.8,.7]],'Квадрат 2×2 разбит на 4 квадрата 1×1')}</div>
${STEPS('Пример 1 (лёгкий). Задача про ковёр.',[
'Делим ковёр на 4 квадрата 1×1. Клеток 4, капель 5 → в каком-то квадрате две капли.',
'Внутри квадрата 1×1 самое большое расстояние — диагональ: √2 ≈ 1,41 м < 1,5 м ✅.'])}
${STEPS('Пример 2. На отрезке длины 10 отметили 11 точек. Докажи, что две из них на расстоянии не больше 1.',[
'Делим отрезок на 10 кусочков длины 1. Точек 11 > 10.',
'Две точки на одном кусочке — между ними не больше 1. (А 10 точек можно расставить с шагом 10 : 9 ≈ 1,11 — так что 11 — наименьшее число.)'])}
${STEPS('Пример 3 (потруднее). Какое наибольшее число королей можно поставить на доску 8×8, чтобы они не били друг друга?',[
'Разобьём доску на 16 квадратиков 2×2. В квадратике 2×2 все клетки — соседи, поэтому двух королей там быть не может.',
'Значит, королей не больше 16 (иначе по Дирихле два окажутся в одном квадратике).',
'А 16 поставить можно — в левый нижний угол каждого квадратика. Ответ: <b>16</b>. Так решают задачи «оценка + пример».'])}
<div class="box err"><b>Частая ошибка</b>Делить на «неудобные» части. Части нужно выбирать так, чтобы две точки в одной части давали то, что требуется в задаче (расстояние, бой королей и т. д.).</div>
${CHK([['В квадрат 1×1 бросили 51 точку. Докажи, что какие-то 3 лежат в квадрате 0,2×0,2. Сколько частей?','25 квадратиков 0,2×0,2. ⌈51 : 25⌉ = 3 ✅.'],['Сколько королей можно поставить на доску 6×6, чтобы они не били друг друга?','9: 9 квадратиков 2×2, по королю в каждом.']])}
${REM('В геометрии клетки рисуешь сам: разбей фигуру на части нужного размера.','«Нарежь пиццу на куски — две оливки попадут на один кусок».')}`},

{title:'★ Рукопожатия, суммы и делимость',lvl:6,html:`
<p class="hook">В любой компании найдутся двое, у которых одинаковое число друзей в этой компании. В любой! Хоть в классе, хоть на сервере из миллиона игроков. Звучит как магия — а это опять кролики.</p>
<div class="box rule"><b>Приём «два значения не бывают одновременно»</b>Иногда клеток столько же, сколько кроликов, но две клетки <b>не могут быть заняты одновременно</b>. Тогда реально клеток на одну меньше — и Дирихле срабатывает.</div>
${STEPS('Пример 1. В компании n человек. Докажи, что у двоих одинаковое число знакомых.',[
'Число знакомых — от 0 до n − 1: это n клеток для n человек. Пока не хватает!',
'Но 0 и n − 1 одновременно не бывает: если кто-то знаком со всеми, то ни у кого нет 0 знакомых.',
'Значит, реально занято не больше n − 1 клеток, а людей n. По Дирихле двое в одной клетке ✅.'])}
${STEPS('Пример 2. Из чисел 1, 2, …, 20 выбрали 11. Докажи, что одно из выбранных делится на другое.',[
'Каждое число = (нечётное) · (степень двойки): 12 = 3 · 4, 20 = 5 · 4, 7 = 7 · 1. Клетка числа — его <b>нечётная часть</b>.',
'Нечётных чисел от 1 до 20 — 10 штук: 10 клеток. Выбрано 11 чисел → два с одной нечётной частью, например 6 = 3 · 2 и 12 = 3 · 4.',
'Числа с одной нечётной частью отличаются только степенью двойки → меньшее делит большее ✅.'])}
${STEPS('Пример 3. Даны 5 чисел: 3, 8, 6, 2, 9. Докажи, что можно выбрать несколько подряд идущих, сумма которых делится на 5.',[
'Считаем «суммы с начала»: 3, 11, 17, 19, 28. Их 5 — по одной для каждого конца.',
'Остатки при делении на 5: 3, 1, 2, 4, 3. Если бы встретился 0 — готово. Нет нуля → 5 сумм в 4 клетках (1–4) → две совпали: 3 и 28.',
'Разность 28 − 3 = 25 — это сумма чисел между ними: 8 + 6 + 2 + 9 = 25 ✅.'])}
${CHK([['Почему среди 11 чисел из 1…20 найдутся два соседних (с разностью 1)?','Клетки — пары (1, 2), (3, 4), …, (19, 20): их 10. 11 чисел → два в одной паре.'],['На турнире 8 команд, каждая с каждой играет не больше одного раза. Докажи, что в любой момент у двух команд одинаковое число сыгранных матчей.','Значения 0…7, но 0 и 7 одновременно невозможны → 7 клеток на 8 команд.']])}
${REM('Если клеток столько же, сколько кроликов, ищи две клетки, которые «не дружат», — их нельзя занять одновременно.','«Кто знаком со всеми — не даёт никому быть одиноким».')}`},

{title:'★ Олимпиадные классики',lvl:7,html:`
<p class="hook">Есть числа 1, 11, 111, 1111, … Среди них обязательно найдётся число, которое делится на 2027 (и вообще на любое число, не делящееся на 2 и на 5). Звучит невероятно — а доказательство в три строчки.</p>
${STEPS('Пример 1. Почему среди 1, 11, 111, … есть число, делящееся на 7?',[
'Возьмём 8 чисел: 1, 11, …, 11111111. Остатков при делении на 7 — 7 штук. 8 чисел → у двух остатки совпадают.',
'Остатки по порядку: 1, 4, 6, 5, 2, 0, 1, 4. Например, у 1 и 1111111 остаток один и тот же — 1. Их разность 1111111 − 1 = 1111110 = 111111 · 10 делится на 7.',
'7 не делит 10, значит, 7 делит 111111. Проверка: 111111 = 7 · 15873 ✅. (А в остатках сразу видно: у 111111 остаток 0.)'])}
${STEPS('Пример 2. Докажи: из любых 10 двузначных чисел можно выбрать две непересекающиеся группы с одинаковой суммой.',[
'Непустых групп из 10 чисел — 2<sup>10</sup> − 1 = 1023.',
'Сумма группы — от 10 до 99 · 10 = 990: не больше 981 значения. 1023 > 981 → две группы с одинаковой суммой.',
'Если у них есть общие числа — выбросим их из обеих групп, суммы останутся равными ✅.'])}
${STEPS('Пример 3. На клетчатой бумаге отметили 5 узлов. Докажи, что середина отрезка между какими-то двумя — тоже узел.',[
'Середина имеет целые координаты, если у двух точек x одной чётности и y одной чётности.',
'Варианты чётности (x, y): (чёт, чёт), (чёт, нечёт), (нечёт, чёт), (нечёт, нечёт) — 4 клетки. 5 точек → две в одной клетке ✅.'])}
<div class="fact">Принцип назван в честь немецкого математика Петера Густава Лежёна Дирихле (1805–1859), который применял его в теории чисел. В Германии его называют «принципом ящиков» (Schubfachprinzip), а в англоязычных странах — «принципом голубятни» (pigeonhole principle).</div>
${CHK([['Сколько точек с целыми координатами в пространстве (x, y, z) нужно, чтобы у каких-то двух середина была целой?','Классов чётности 2 · 2 · 2 = 8 → нужно 9 точек.'],['Почему в примере 1 важно, что 7 не делит 10?','Разность двух чисел из единиц = (число из единиц) · 10<sup>k</sup>. Чтобы «перенести» делимость на число из единиц, у 7 и 10 не должно быть общих делителей.']])}
${REM('Ищи клетки среди остатков, чётностей, сумм групп. Сравни количество кроликов и клеток.','«Кроликов больше — двое встретятся. Потом посмотри, что даёт их встреча».')}`},

{title:'Шпаргалка',html:`
<ul class="steps">
<li>Кроликов больше, чем клеток → где-то ≥ 2.</li>
<li>n кроликов в k клетках → где-то ≥ ⌈n : k⌉ (округляем вверх).</li>
<li>Чтобы наверняка m в одной из k клеток → k(m − 1) + 1.</li>
<li>«Наверняка» = самый невезучий случай + 1.</li>
<li>Остатков при делении на n — n штук; n + 1 число → разность двух кратна n.</li>
<li>В геометрии — разбей фигуру на части.</li>
<li>Две «несовместимые» клетки → клеток на одну меньше.</li></ul>
${CHK([['Как называется принцип по-английски?','Pigeonhole principle — «принцип голубятни».']])}`}
];

/* ---------- symbols ---------- */
const symbols={tab:'Формулы',title:'Формулы и приёмы',rows:[
['n > k','кроликов больше, чем клеток','Хотя бы в одной клетке не меньше двух.','13 учеников, 12 месяцев'],
['n < k','клеток больше, чем кроликов','Хотя бы одна клетка пустая.','9 конфет, 10 коробок'],
['⌈x⌉','«округление вверх»','Наименьшее целое, не меньшее x.','⌈3,2⌉ = 4, ⌈3⌉ = 3'],
['⌈n : k⌉','обобщённый принцип','Столько кроликов наверняка в какой-то клетке.','⌈25 : 7⌉ = 4'],
['k(m − 1) + 1','сколько нужно кроликов','Чтобы в одной из k клеток наверняка было m.','5 · 2 + 1 = 11'],
['+ 1','«наверняка»','Самый невезучий случай плюс один.','3 цвета → 4 носка'],
['a ≡ b (mod n)','одинаковые остатки','Разность a − b делится на n.','28 и 3 при делении на 5'],
['n + 1','числа и остатки','Среди n + 1 чисел два с разностью, кратной n.','6 чисел, n = 5']
],after:`<div class="box tip" style="margin-top:14px"><b>Самое важное</b>Сначала назови кроликов и клетки. Потом сравни, кого больше.</div>`};

/* =================== generators =================== */
const MONTH={name:'месяц',k:12,cl:'месяцы',w:'в одном месяце'};
const CTX=[
 {who:'учеников',one:'ученик',k:12,cage:'месяцы года',same:'родились в одном месяце'},
 {who:'друзей',one:'друг',k:7,cage:'дни недели',same:'родились в один день недели'},
 {who:'игроков на сервере',one:'игрок',k:24,cage:'скины (их 24)',same:'выбрали одинаковый скин',pre:'В игре 24 скина, каждый игрок выбрал один.'},
 {who:'школьников',one:'школьник',k:33,cage:'буквы алфавита (их 33)',same:'имеют фамилии на одну букву',pre:'В русском алфавите 33 буквы.'},
 {who:'гостей',one:'гость',k:10,cage:'последние цифры номера (от 0 до 9)',same:'имеют телефоны с одинаковой последней цифрой'}];

/* L0 */
G(0,()=>CH('Как звучит принцип Дирихле? Если кроликов больше, чем клеток, то…','хотя бы в одной клетке не меньше двух кроликов',['в каждой клетке не меньше двух кроликов','все кролики сидят в одной клетке','обязательно есть пустая клетка'],
 {short:'«Хотя бы в одной» — а не «в каждой».',
 explain:'Принцип Дирихле: кроликов больше, чем клеток → <b>хотя бы в одной</b> клетке не меньше двух кроликов. Почему: если бы в каждой клетке было не больше одного, кроликов было бы не больше, чем клеток.<br>«В каждой по два» — неверно: 4 кролика в 3 клетках могут сидеть как 2, 1, 1. «Есть пустая клетка» — тоже не обязательно.',
 explain2:'Пример: 4 кролика, 3 клетки. Варианты: 2 + 1 + 1, 2 + 2 + 0, 3 + 1 + 0, 4 + 0 + 0. Во всех есть клетка с двумя или больше. Но пустая клетка есть не всегда, и «по два в каждой» нет ни разу.'}),'r');
G(0,()=>{const c=pick(CTX);const n=c.k+R(1,8);return CH(`${c.pre?c.pre+' ':''}Есть ${n} ${c.who}. Докажи, что двое ${c.same}. Что здесь «клетки»?`,c.cage,[c.who.replace(/ .*/,''),'числа от 1 до '+n,'пары '+c.who.replace(/ .*/,'')],
 {short:`Клетки — ${c.cage}, кролики — ${c.who} (${n}).`,
 explain:`«Кролики» — то, что раскладываем: ${c.who} (${n}). «Клетки» — то, по чему раскладываем: <b>${c.cage}</b> (их ${c.k}).<br>${n} > ${c.k} → двое в одной клетке, то есть ${c.same}.`,
 explain2:`Подсказка для любых задач: клетки — это «варианты признака», по которому ищем совпадение (месяц, цвет, остаток). Кролики — объекты, у которых этот признак есть.`});},'r');
G(0,()=>{const c=pick(CTX);const n=c.k+R(-4,4);const yes=n>c.k;return YN(`${c.pre?c.pre+' ':''}Собрались ${n} ${c.who}. Обязательно ли найдутся двое, которые ${c.same}?`,yes,{
 short:yes?`Да: ${n} > ${c.k}.`:`Нет: ${n} ≤ ${c.k}, всем может хватить своей «клетки».`,
 explain:`Клетки — ${c.cage}: их ${c.k}. Кролики — ${c.who}: их ${n}.<br>${yes?`${n} > ${c.k} — кроликов больше. По принципу Дирихле двое попадут в одну клетку. Ответ: <b>обязательно</b>.`:`${n} ≤ ${c.k} — может оказаться, что у всех разные «клетки». Совпадение возможно, но не обязательно. Ответ: <b>не обязательно</b>.`}`,
 explain2:yes?`Попробуй рассадить ${n} по ${c.k} клеткам по одному: ${c.k} займут все клетки, ещё ${n-c.k} ${plural(n-c.k,'останется','останутся','останутся')} — им придётся к кому-то подсесть.`:`Пример «без совпадений»: каждый занимает свою клетку, и ещё ${c.k-n} ${plural(c.k-n,'клетка остаётся','клетки остаются','клеток остаются')} пустыми.`},['Обязательно','Не обязательно']);});
G(0,()=>{const c=pick(CTX);return {type:'num',q:`${c.pre?c.pre+' ':''}Какое наименьшее число ${c.who.replace('игроков на сервере','игроков')} нужно, чтобы <b>наверняка</b> нашлись двое, которые ${c.same}?`,ans:c.k+1,
 short:`Клеток ${c.k} → ${c.k} + 1 = ${c.k+1}.`,
 explain:`Клетки — ${c.cage}: ${c.k}. Если ${c.who.replace(/ .*/,'')} ${c.k}, у всех могут быть разные клетки — совпадения нет. А если ${c.k+1} — кроликов больше, чем клеток. Ответ: <b>${c.k+1}</b>.`,
 explain2:`Самый невезучий случай: первые ${c.k} попали в разные клетки. Следующий, ${c.k+1}-й, обязательно попадёт в занятую.`};});
G(0,()=>{const k=R(5,15),n=k+R(-4,3);const yes=n<k;return YN(`В ${k} ${plural(k,'коробку','коробки','коробок')} разложили ${n} ${plural(n,'конфету','конфеты','конфет')}. Обязательно ли есть пустая коробка?`,yes,{
 short:yes?`Да: если бы в каждой коробке была конфета, их было бы не меньше ${k}.`:`Нет: ${n} ≥ ${k}, можно положить по конфете в каждую коробку.`,
 explain:yes?`Предположим, что пустых коробок нет: в каждой хотя бы одна конфета. Тогда конфет не меньше ${k}. А их ${n} < ${k} — противоречие. Ответ: <b>обязательно</b>.`:`Конфет ${n}, коробок ${k}: ${n} ≥ ${k}. Кладём по одной конфете в каждую коробку${n>k?`, а оставшиеся ${n-k} — куда угодно`:''}. Пустых нет. Ответ: <b>не обязательно</b>.`,
 explain2:`Это принцип Дирихле «наоборот»: клеток больше, чем кроликов → какая-то клетка пустая. Здесь клеток ${k}, кроликов ${n}.`},['Обязательно','Не обязательно']);});

/* L1 */
G(1,()=>CH('Как решать задачи «сколько взять, чтобы <b>наверняка</b>…»?','Представить самый невезучий случай и добавить 1',['Представить самый везучий случай','Взять половину всех предметов','Сложить количества всех видов'],
 {short:'«Наверняка» = невезение + 1.',
 explain:'«Наверняка» значит «даже при самом большом невезении». Поэтому считаем, сколько можно вытащить <b>неудачно</b> (так, что нужного ещё нет), и добавляем 1. Везучий случай не подходит: везение не гарантировано.',
 explain2:'Носки трёх цветов, нужна пара. Везучий случай — 2 носка. Но «наверняка» — это невезение: по одному каждого цвета (3), и только 4-й даст пару.'}),'r');
G(1,()=>{const k=R(2,5);const names=['чёрных','белых','серых','синих','красных'].slice(0,k);const cnt=names.map(()=>R(2,9));const g=guarantee(cnt,x=>x.some(v=>v>=2));ok(g.n===k+1,'socks pair');
 return {type:'num',q:`В ящике ${names.map((nm,i)=>`${cnt[i]} ${nm}`).join(', ')} носков. Сколько носков нужно вытащить не глядя, чтобы <b>наверняка</b> получилась пара одного цвета?`,ans:g.n,
 short:`Невезение: по одному каждого из ${k} цветов. Ответ: ${k} + 1 = ${g.n}.`,
 explain:`Шаг 1. Невезучий случай: вытащили по одному носку каждого цвета — ${k} ${plural(k,'носок','носка','носков')}, пары нет.<br>Шаг 2. Следующий носок совпадёт по цвету с одним из уже вытащенных. Ответ: <b>${g.n}</b>.<br>Сколько носков каждого цвета — неважно (лишь бы хватало).`,
 explain2:`Это принцип Дирихле: клетки — цвета (${k}), кролики — носки. Чтобы двое попали в одну клетку, нужно ${k} + 1 кролик.`};});
G(1,()=>{const a=R(3,9),b=R(3,12),c=Math.random()<0.5?R(2,8):0;const m=R(2,3);const cnt=c?[a,b,c]:[a,b];const g=guarantee(cnt,x=>x[0]>=m);ok(g.n===(c?b+c:b)+m,'socks color');
 return {type:'num',q:`В сундуке ${a} ${plural(a,'алмаз','алмаза','алмазов')}, ${b} ${plural(b,'изумруд','изумруда','изумрудов')}${c?` и ${c} ${plural(c,'рубин','рубина','рубинов')}`:''}. Сколько камней нужно вынуть вслепую, чтобы <b>наверняка</b> среди них было ${m} ${plural(m,'алмаз','алмаза','алмазов')}?`,ans:g.n,
 short:`Невезение: все ${c?b+c:b} не-алмазов + ${m-1} ${plural(m-1,'алмаз','алмаза','алмазов')}. Ответ: ${g.n}.`,
 explain:`Шаг 1. Самый невезучий случай: сначала выходят <b>все</b> не-алмазы: ${b}${c?` + ${c} = ${b+c}`:''}.<br>Шаг 2. Потом ещё ${m-1} ${plural(m-1,'алмаз','алмаза','алмазов')} — а нужно ${m}. Итого «неудачно»: ${c?b+c:b} + ${m-1} = ${g.n-1}.<br>Шаг 3. Следующий камень — точно алмаз (другие кончились). Ответ: <b>${g.n}</b>.`,
 explain2:`Частая ошибка — ответить ${m} («вытащу ${m} алмаза»). Это везучий случай. А мы должны быть уверены, даже если алмазы выходят последними.`};});
G(1,()=>{const a=R(3,9),b=R(2,9),c=R(2,9);const g=guarantee([a,b,c],x=>x[0]>=1&&x[2]>=1);
 return {type:'num',q:`В сундуке ${a} ${plural(a,'меч','меча','мечей')}, ${b} ${plural(b,'щит','щита','щитов')} и ${c} ${plural(c,'лук','лука','луков')}. Сколько предметов нужно вынуть вслепую, чтобы <b>наверняка</b> был хотя бы один меч и хотя бы один лук?`,ans:g.n,
 short:`Невезение: ${g.worst[0]?`все мечи и щиты (${a+b})`:`все щиты и луки (${b+c})`}. Ответ: ${g.n}.`,
 explain:`Шаг 1. Плохо, если нет мечей <b>или</b> нет луков. Без мечей можно вытащить щиты и луки: ${b} + ${c} = ${b+c}. Без луков — мечи и щиты: ${a} + ${b} = ${a+b}.<br>Шаг 2. Самый невезучий случай — больший из них: ${Math.max(a+b,b+c)}.<br>Шаг 3. Ответ: ${Math.max(a+b,b+c)} + 1 = <b>${g.n}</b>.`,
 explain2:`Ошибка — взять меньший вариант (${Math.min(a+b,b+c)} + 1 = ${Math.min(a+b,b+c)+1}). Тогда «невезение» с ${a+b>=b+c?'мечами и щитами':'щитами и луками'} нас обманет: ${Math.max(a+b,b+c)} предметов, а нужного всё нет.`};});
G(1,()=>{const n=R(2,8),m=R(2,8);const g=guarantee([n,n,m,m],x=>(x[0]&&x[1])||(x[2]&&x[3]));ok(g.n===n+m+1,'gloves');
 return {type:'num',q:`В шкафу ${n} ${plural(n,'пара','пары','пар')} чёрных и ${m} ${plural(m,'пара','пары','пар')} коричневых перчаток. Сколько перчаток нужно вытащить не глядя, чтобы <b>наверняка</b> получилась пара (левая и правая одного цвета)?`,ans:g.n,
 hint:'Перчатки бывают левые и правые!',
 short:`Невезение: все ${n+m} левых. Ответ: ${g.n}.`,
 explain:`Шаг 1. Невезучий случай: все левые перчатки — ${n} чёрных + ${m} коричневых = ${n+m}. Пары нет!<br>Шаг 2. Следующая перчатка — правая, и к ней уже есть левая того же цвета. Ответ: ${n+m} + 1 = <b>${g.n}</b>.<br>Типичная ошибка — ответ 3, как с носками. Но носки одинаковые, а перчатки — левые и правые.`,
 explain2:`Можно невезение и иначе: все чёрные левые (${n}) и все коричневые правые (${m}) — тоже ${n+m} без пары. Больше без пары взять нельзя: для каждого цвета можно брать только одну сторону.`};});

/* L2 */
G(2,()=>CH('Обобщённый принцип Дирихле: n кроликов сидят в k клетках. Что можно гарантировать?','Хотя бы в одной клетке не меньше ⌈n : k⌉ кроликов',['В каждой клетке ровно n : k кроликов','Хотя бы в одной клетке не больше ⌈n : k⌉ кроликов','В каждой клетке не меньше ⌈n : k⌉ кроликов'],
 {short:'«Где-то не меньше» — и округляем вверх.',
 explain:'Если бы в каждой клетке было меньше ⌈n : k⌉, то есть не больше ⌈n : k⌉ − 1, кроликов было бы меньше n. Значит, <b>хотя бы в одной</b> клетке их <b>не меньше ⌈n : k⌉</b>. Про «каждую» клетку ничего сказать нельзя.',
 explain2:'Пример: 25 кроликов, 7 клеток. ⌈25 : 7⌉ = 4. Рассадка 4, 4, 4, 4, 3, 3, 3 — максимум 4. Рассадка 25, 0, 0, … — максимум 25. В любой рассадке где-то не меньше 4.'}),'r');
G(2,()=>{let n,k;do{n=R(10,60);k=R(3,9);}while(n%k===0&&Math.random()<0.6);const a=ceil(n,k),d=Math.floor(n/k);const wrong=[String(d===a?a+1:d),String(a+1===d?a+2:a+1),(n/k).toFixed(2).replace('.',',')].filter((x,i,s)=>x!==String(a)&&s.indexOf(x)===i);while(wrong.length<3)wrong.push(String(a+wrong.length+1));
 return CH(`Чему равно ⌈${n} : ${k}⌉ (деление с округлением вверх)?`,String(a),wrong.slice(0,3),{
 short:`${n} : ${k} = ${d}${n%k?`, остаток ${n%k} → вверх: ${a}`:''}.`,
 explain:`${n} : ${k} = ${d}${n%k?` и остаток ${n%k}`:' ровно'}. ${n%k?`Есть остаток — округляем вверх: <b>${a}</b>.`:`Делится нацело — округлять не нужно: <b>${a}</b>.`}<br>Смысл: если в каждую из ${k} клеток посадить по ${a-1}, поместится только ${k*(a-1)} < ${n} — значит, где-то не меньше ${a}.`,
 explain2:`⌈x⌉ — наименьшее целое число, которое не меньше x. ${n} : ${k} ≈ ${(n/k).toFixed(2).replace('.',',')} → ${a}. Обычное округление «до ближайшего» тут не годится: ⌈3,1⌉ = 4.`});},'r');
G(2,()=>{const ctx=pick([['игроков','командам',10,60,3,9],['учеников','классам',50,200,4,9],['конфет','коробкам',20,80,3,10],['монет','кошелькам',15,70,3,8]]);let n,k;do{n=R(ctx[2],ctx[3]);k=R(ctx[4],ctx[5]);}while(n%k===0);const a=ceil(n,k);
 const ev=range(1,k).map((_,i)=>i<n%k?a:a-1);ok(ev.reduce((x,y)=>x+y,0)===n,'even');
 return {type:'num',q:`${n} ${ctx[0]} распределили по ${k} ${ctx[1]}. Какое наибольшее число ${ctx[0]} можно гарантировать в самой заполненной из них? (То есть: «где-то наверняка не меньше …»)`,ans:a,
 short:`⌈${n} : ${k}⌉ = ${a}.`,
 explain:`Шаг 1. Если бы везде было не больше ${a-1}, то всего не больше ${k} · ${a-1} = ${k*(a-1)} < ${n}. Значит, где-то не меньше <b>${a}</b>.<br>Шаг 2. Больше гарантировать нельзя: распределение ${ev.join(', ')} даёт максимум ровно ${a}.`,
 explain2:`Раздаём «по кругу», как карты: каждому по ${Math.floor(n/k)} — ушло ${k*Math.floor(n/k)}, осталось ${n%k}. Эти ${n%k} получат по ещё одному — у них станет ${a}.`};});
G(2,()=>{const N=R(400,2500);const a=ceil(N,366);return {type:'num',q:`В городе ${N} школьников. Найдётся ли день года, в который родились сразу несколько из них? Какое наибольшее число школьников с общим днём рождения можно <b>гарантировать</b>? (Учти високосный год: 366 дней.)`,ans:a,
 short:`⌈${N} : 366⌉ = ${a}.`,
 explain:`Клетки — дни года. Берём худший случай — 366 дней (с 29 февраля). Кролики — ${N} школьников.<br>Если бы в каждый день родилось не больше ${a-1}, школьников было бы не больше 366 · ${a-1} = ${366*(a-1)} < ${N}. Значит, есть день, в который родились не меньше <b>${a}</b>.`,
 explain2:`${N} : 366 ≈ ${(N/366).toFixed(2).replace('.',',')}, вверх — ${a}. А гарантировать ${a+1} нельзя: школьники могли распределиться почти поровну, по ${a-1} или ${a} на день (всего 366 · ${a} = ${366*a} ≥ ${N}).`};});
G(2,()=>{const m=R(6,15);let n;do{n=R(2*(m+1)+1,5*(m+1));}while(n%(m+1)===0);const a=ceil(n,m+1);return {type:'num',q:`${n} учеников написали контрольную. Больше всех ошибок — ${m} — сделал Вова, у остальных меньше. Какое наибольшее число учеников с <b>одинаковым</b> количеством ошибок можно гарантировать?`,ans:a,
 hint:'Сколько разных значений может принимать число ошибок?',
 short:`Значений 0…${m} — это ${m+1}; ⌈${n} : ${m+1}⌉ = ${a}.`,
 explain:`Шаг 1. Клетки — число ошибок: 0, 1, …, ${m} — всего <b>${m+1}</b> (ноль тоже!).<br>Шаг 2. Кролики — ${n} учеников. ⌈${n} : ${m+1}⌉ = <b>${a}</b>.<br>Шаг 3. Значит, найдутся ${a} ученика с одинаковым числом ошибок. Больше гарантировать нельзя: ученики могли распределиться по ${a-1}–${a} на каждое значение.`,
 explain2:`Типичная ошибка — забыть «0 ошибок» и взять ${m} клеток. Тогда получится ⌈${n} : ${m}⌉ = ${ceil(n,m)}${ceil(n,m)!==a?' — неверно':''}. Значения от 0 до ${m} — это ${m+1} вариантов.`};});

/* L3 */
G(3,()=>CH('Сколько кроликов нужно, чтобы в одной из k клеток <b>наверняка</b> оказалось m кроликов?','k · (m − 1) + 1',['k · m','k · m + 1','k + m − 1'],
 {short:'По m − 1 в каждую клетку — и ещё один.',
 explain:'Невезучий случай: в каждой из k клеток по m − 1 кролику — это k(m − 1) кроликов, и нигде нет m. Следующий кролик в любой клетке сделает m. Ответ: <b>k(m − 1) + 1</b>.<br>k · m — слишком много: уже при k(m − 1) + 1 гарантия есть.',
 explain2:'Проверка на m = 2: k · 1 + 1 = k + 1 — это обычный принцип Дирихле (кроликов на одного больше, чем клеток).'}),'r');
G(3,()=>{const k=R(3,8),m=R(3,6);const ans=k*(m-1)+1;return {type:'num',q:`В Roblox-кейсе выпадают предметы ${k} разных редкостей (каждой — сколько угодно). Сколько кейсов нужно открыть, чтобы <b>наверняка</b> получить ${m} ${plural(m,'предмет','предмета','предметов')} одной редкости?`,ans,
 short:`${k} · ${m-1} + 1 = ${ans}.`,
 explain:`Шаг 1. Невезение: по ${m-1} ${plural(m-1,'предмету','предмета','предметов')} каждой редкости — ${k} · ${m-1} = ${k*(m-1)} кейсов, и ни одной редкости ${m} раз.<br>Шаг 2. Следующий кейс даст ${m}-й предмет какой-то редкости. Ответ: <b>${ans}</b>.`,
 explain2:`Формула k(m − 1) + 1 при k = ${k}, m = ${m}. Проверь: ${k*(m-1)} мало (пример — по ${m-1} каждой редкости), а ${ans} хватает по обобщённому принципу: ⌈${ans} : ${k}⌉ = ${ceil(ans,k)}.`};});
G(3,()=>{const m=R(3,6),k=pick([12,7]);const ans=k*(m-1)+1;const w=k===12?'в одном месяце':'в один день недели';return {type:'num',q:`Какое наименьшее число учеников должно быть в школе, чтобы <b>наверняка</b> нашлись ${m} ${plural(m,'ученик','ученика','учеников')}, родившихся ${w}?`,ans,
 short:`${k} · ${m-1} + 1 = ${ans}.`,
 explain:`Клеток ${k} (${k===12?'месяцев':'дней недели'}). Невезение: по ${m-1} в каждой — ${k*(m-1)} учеников, и ${m} одинаковых нет. Ответ: ${k*(m-1)} + 1 = <b>${ans}</b>.`,
 explain2:`Обобщённый принцип: при ${ans} учениках ⌈${ans} : ${k}⌉ = ${m} ✅, а при ${ans-1}: ⌈${ans-1} : ${k}⌉ = ${ceil(ans-1,k)} — мало.`};});
G(3,()=>{let cnt,m,g,naive;do{cnt=[R(1,6),R(4,12),R(4,12)];m=R(3,5);g=guarantee(cnt,x=>x.some(v=>v>=m));naive=3*(m-1)+1;}while(cnt.every(c=>c<m)||(Math.random()<0.6&&g.n===naive));
 const nm=['красных','синих','зелёных'];
 return {type:'num',q:`В ящике ${cnt.map((c,i)=>`${c} ${nm[i]}`).join(', ')} носков. Сколько носков нужно вытащить не глядя, чтобы <b>наверняка</b> было ${m} ${plural(m,'носок','носка','носков')} одного цвета?`,ans:g.n,
 hint:'Проверь честно самый невезучий случай: каких-то носков может не хватить даже до '+(m-1)+'.',
 short:`Невезение: ${g.worst.map((v,i)=>`${v} ${nm[i]}`).join(' + ')} = ${g.n-1}. Ответ: ${g.n}.`,
 explain:`Шаг 1. Невезение: берём каждого цвета как можно больше, но меньше ${m}: ${cnt.map((c,i)=>`${nm[i]} — ${Math.min(c,m-1)}${c<m-1?` (больше нет!)`:''}`).join(', ')}.<br>Шаг 2. Итого «неудачно»: ${g.worst.join(' + ')} = ${g.n-1}.<br>Шаг 3. Ответ: <b>${g.n}</b>.${g.n!==naive?`<br>Формула 3 · ${m-1} + 1 = ${naive} здесь не годится: ${cnt.filter(c=>c<m-1).length?'каких-то носков меньше '+(m-1):''}.`:''}`,
 explain2:`Следующий носок после ${g.n-1} неудачных может быть только того цвета, где уже ${m-1}${cnt.some(c=>c<m)?` (цвета, где носков меньше ${m}, кончились)`:''} — и станет ${m}.`};});
G(3,()=>{const m=R(3,9);let n;do{n=R(20,90);}while(n%m===0);const a=ceil(n,m);return {type:'num',q:`${n} игроков нужно разместить по комнатам так, чтобы в каждой было не больше ${m}. Какое наименьшее число комнат понадобится?`,ans:a,
 short:`⌈${n} : ${m}⌉ = ${a}.`,
 explain:`В ${a-1} ${plural(a-1,'комнату','комнаты','комнат')} по ${m} помещается только ${(a-1)*m} < ${n} — не хватит. В ${a} ${plural(a,'комнату','комнаты','комнат')} — до ${a*m} ≥ ${n}, хватит. Ответ: <b>${a}</b>.`,
 explain2:`Это тот же принцип Дирихле «с другой стороны»: если комнат k и в каждой ≤ ${m}, то игроков ≤ ${m}k. Нужно ${m}k ≥ ${n} → k ≥ ${n} : ${m} ≈ ${(n/m).toFixed(2).replace('.',',')} → k = ${a}.`};});

/* L4 */
G(4,()=>{const n=R(3,12);return CH(`Сколько разных остатков может получиться при делении целого числа на ${n}?`,String(n),[String(n-1),String(n+1),'бесконечно много'],
 {short:`0, 1, …, ${n-1} — это ${n}.`,
 explain:`Остаток при делении на ${n} — число от 0 до ${n-1}. Всего <b>${n}</b> вариантов (не забудь 0!). Поэтому остатки — удобные «клетки»: их ровно ${n}.`,
 explain2:`Выпиши остатки чисел 0, 1, 2, …: ${range(0,n+2).map(x=>x%n).join(', ')}, … — они повторяются по кругу из ${n} значений.`});},'r');
G(4,()=>{const n=R(3,9);return CH(`Когда разность двух целых чисел делится на ${n}?`,`Когда их остатки при делении на ${n} одинаковые`,[`Только когда оба числа делятся на ${n}`,`Когда сумма их остатков равна ${n}`,`Когда одно из чисел делится на ${n}`],
 {short:'Одинаковые остатки «сокращаются» при вычитании.',
 explain:`Если a = ${n}q₁ + r и b = ${n}q₂ + r (остаток r один), то a − b = ${n}(q₁ − q₂) — делится на ${n}. Поэтому: разность делится на ${n} ⇔ <b>остатки равны</b>. «Оба делятся на ${n}» — только частный случай (остатки 0 и 0).`,
 explain2:`Пример: ${n+2} и ${3*n+2} — остатки 2 и 2, разность ${2*n} делится на ${n}. Ни одно из чисел на ${n} не делится, а разность — делится.`});},'r');
G(4,()=>{const n=R(4,15);return {type:'num',q:`Какое наименьшее количество целых чисел нужно взять, чтобы среди них <b>наверняка</b> нашлись два, разность которых делится на ${n}?`,ans:n+1,
 short:`Остатков ${n} → нужно ${n} + 1 = ${n+1}.`,
 explain:`Клетки — остатки при делении на ${n}: их ${n} (0, 1, …, ${n-1}). Разность делится на ${n}, если остатки одинаковые.<br>${n} чисел могут иметь все разные остатки (например, 1, 2, …, ${n}). А ${n+1} число — уже нет. Ответ: <b>${n+1}</b>.`,
 explain2:`Невезучий случай: числа 0, 1, 2, …, ${n-1} — разности от 1 до ${n-1}, ни одна не делится на ${n}. Добавь любое число — его остаток совпадёт с остатком одного из них.`};});
G(4,()=>{const n=R(5,11);let nums,pairs;do{nums=sample(range(10,150),n+1);pairs=[];for(let i=0;i<nums.length;i++)for(let j=i+1;j<nums.length;j++)if((nums[i]-nums[j])%n===0)pairs.push([nums[i],nums[j]]);}while(pairs.length!==1);
 const [p,q]=pairs[0];const wrong=[];while(wrong.length<3){const [x,y]=sample(nums,2);if((x-y)%n!==0){const s=`${Math.max(x,y)} и ${Math.min(x,y)}`;if(!wrong.includes(s))wrong.push(s);}}
 const right=`${Math.max(p,q)} и ${Math.min(p,q)}`;
 return CH(`Даны ${n+1} чисел: ${nums.join(', ')}. Какие два из них имеют разность, делящуюся на ${n}?`,right,wrong,{
 hint:`Найди остатки при делении на ${n}.`,
 short:`Одинаковый остаток ${p%n}: ${Math.max(p,q)} − ${Math.min(p,q)} = ${Math.abs(p-q)}.`,
 explain:`Остатки при делении на ${n}: ${nums.map(x=>`${x} → ${x%n}`).join(', ')}.<br>Одинаковые остатки только у ${p} и ${q} (остаток ${p%n}). Их разность ${Math.max(p,q)} − ${Math.min(p,q)} = ${Math.abs(p-q)} = ${n} · ${Math.abs(p-q)/n} ✅.<br>Чисел ${n+1}, остатков ${n} — по принципу Дирихле такая пара обязана была найтись.`,
 explain2:`Можно проверять разности напрямую, но это долго: пар много. Остатки — быстрее: «клеток» ${n}, «кроликов» ${n+1}, ищем двух в одной клетке.`});});
G(4,()=>{const n=R(4,12);return CH(`Почему среди любых ${n+1} целых чисел найдутся два с разностью, делящейся на ${n}?`,`Остатков при делении на ${n} всего ${n}, а чисел ${n+1} — у двух чисел остаток одинаковый`,[`Потому что среди ${n+1} чисел одно обязательно делится на ${n}`,`Потому что среди них есть два соседних числа`,`Потому что сумма всех ${n+1} чисел делится на ${n}`],
 {short:'Остатки — клетки, числа — кролики.',
 explain:`Клетки — остатки (${n} штук), кролики — числа (${n+1}). По принципу Дирихле два числа с одним остатком, а их разность делится на ${n}.<br>«Одно делится на ${n}» — неверно: числа 1, ${n+1}, ${2*n+1}, … — ни одно не делится на ${n}.`,
 explain2:`Пример: ${range(1,n+1).map(i=>i*n+1).slice(0,4).join(', ')}… — все дают остаток 1. Ни одно не делится на ${n}, но любые два имеют разность, кратную ${n}.`});});

/* L5 */
G(5,()=>CH('Как применять принцип Дирихле в геометрических задачах?','Разбить фигуру на части (клетки), а точки считать кроликами',['Измерить расстояния между всеми точками','Провести через точки окружность','Найти самую дальнюю точку'],
 {short:'Клетки в геометрии рисуешь сам.',
 explain:'В геометрии клеток нет — их придумываешь ты: разбиваешь фигуру на части нужного размера. Если точек больше, чем частей, две окажутся в одной части — и расстояние между ними не больше размера части.',
 explain2:'Квадрат 2×2 и 5 точек: делим на 4 квадрата 1×1. Две точки в одном квадрате — между ними не больше диагонали √2.'}),'r');
G(5,()=>{const L=R(3,20);return {type:'num',q:`На отрезке длины ${L} отмечают точки. Какое наименьшее число точек нужно отметить, чтобы <b>наверняка</b> нашлись две на расстоянии не больше 1 друг от друга?`,ans:L+1,
 short:`${L} кусочков по 1 → ${L+1} точек. (${L} точек можно расставить с шагом ${L}:${L-1} > 1.)`,
 explain:`Шаг 1. Делим отрезок на ${L} кусочков длины 1 — это клетки. При ${L+1} точках две попадут на один кусочек → расстояние между ними ≤ 1.<br>Шаг 2. ${L} точек мало: расставим их равномерно от начала до конца, шаг ${L} : ${L-1} ≈ ${(L/(L-1)).toFixed(2).replace('.',',')} > 1.<br>Ответ: <b>${L+1}</b>.`,
 explain2:`Это задача «оценка + пример»: оценка (${L+1} точек точно хватит) — по Дирихле; пример (${L} не хватит) — равномерная расстановка.`};});
G(5,()=>{const m=R(2,5);let N;do{N=R(m*m+1,6*m*m);}while(N%(m*m)===0);const a=ceil(N,m*m);
 const pts=range(1,Math.min(N,40)).map(()=>[Math.random()*.94+.03,Math.random()*.94+.03]);
 return {type:'num',q:`В квадрат 1×1 бросили ${N} ${plural(N,'точку','точки','точек')} (ни одна не лежит на линиях разреза). Квадрат разрезали на ${m}×${m} = ${m*m} равных квадратиков. Сколько точек <b>наверняка</b> окажется в каком-то одном квадратике?`,ans:a,pic:sqPts(m,pts),
 short:`⌈${N} : ${m*m}⌉ = ${a}.`,
 explain:`Клетки — квадратики: ${m*m}. Кролики — точки: ${N}.<br>Если бы в каждом было не больше ${a-1}, точек было бы не больше ${m*m} · ${a-1} = ${m*m*(a-1)} < ${N}. Значит, где-то не меньше <b>${a}</b>.`,
 explain2:`${N} : ${m*m} ≈ ${(N/(m*m)).toFixed(2).replace('.',',')}, округляем вверх: ${a}. Больше гарантировать нельзя — точки могли распределиться почти поровну.`};});
G(5,()=>{const n=R(3,10);const ans=Math.ceil(n/2)**2;
 // brute force check for small boards
 if(n<=5){let best=0;const cells=range(0,n*n-1);const put=[];const rec=i=>{if(i===cells.length){best=Math.max(best,put.length);return;}if(put.length+(cells.length-i)<=best)return;const r=Math.floor(i/n),c=i%n;if(!put.some(p=>Math.abs(Math.floor(p/n)-r)<=1&&Math.abs(p%n-c)<=1)){put.push(i);rec(i+1);put.pop();}rec(i+1);};rec(0);ok(best===ans,'kings');}
 const b=Math.ceil(n/2);
 return {type:'num',q:`Какое наибольшее число королей можно поставить на доску ${n}×${n}, чтобы никакие два не били друг друга? (Король бьёт все соседние клетки, включая диагональные.)`,ans,
 hint:'Разрежь доску на квадратики 2×2. Сколько королей влезет в один квадратик?',
 short:`${b}² = ${ans}: квадратиков 2×2 ${n%2?'(с краевыми кусочками) ':''}${ans}, в каждом не больше одного короля.`,
 explain:`Шаг 1 (оценка). Разрежем доску на квадратики 2×2${n%2?' (у правого и верхнего края останутся полоски — режем их на кусочки 1×2, 2×1 и угловую клетку 1×1)':''}. Всего частей ${b} · ${b} = ${ans}. В одной части все клетки — соседи, поэтому в ней не больше одного короля. Значит, королей не больше ${ans}.<br>Шаг 2 (пример). Ставим королей на клетки, где оба номера (строки и столбца) нечётные: 1, 3, 5, … — их ${b} · ${b} = ${ans}, и они не бьют друг друга.<br>Ответ: <b>${ans}</b>.`,
 explain2:`Если поставить ${ans+1} королей, то по принципу Дирихле два попадут в одну часть — и будут бить друг друга. А ${ans} поставить можно «через клетку в каждом направлении».`};});
G(5,()=>{const a=pick([2,4,6,10]);const h=a/2;const d=h===1?'√2':`${h}√2`;return CH(`В квадрат со стороной ${a} бросили 5 точек. Как доказать, что какие-то две из них на расстоянии не больше ${d}?`,`Разрезать квадрат на 4 квадрата со стороной ${h}: две точки попадут в один, а диагональ маленького квадрата равна ${d}`,[`Разрезать квадрат на 5 полосок: в каждой будет по точке`,`Разрезать квадрат на 2 прямоугольника: в каком-то будет 3 точки`,`Провести диагонали квадрата: на них будут лежать две точки`],
 {short:`4 квадратика ${h}×${h}, диагональ ${d}.`,
 explain:`Клетки — 4 квадрата ${h}×${h}, кролики — 5 точек. Две точки в одном квадрате, а самое большое расстояние внутри квадрата — его диагональ ${h} · √2 = <b>${d}</b>.<br>Разрез на 2 прямоугольника ${a}×${h} не годится: в нём точки могут быть далеко (диагональ прямоугольника больше ${d}).`,
 explain2:`Части надо выбирать так, чтобы «две точки в одной части» сразу давали нужное расстояние. Диагональ квадрата со стороной s равна s√2 (по теореме Пифагора: s² + s² = 2s²).`});});

/* L6 ★ */
G(6,()=>CH('В компании n человек. Почему у двоих обязательно одинаковое число знакомых?','Значений от 0 до n − 1, но 0 и n − 1 одновременно не бывает — остаётся n − 1 клетка на n человек',['Потому что знакомства всегда взаимные','Потому что каждый с кем-нибудь знаком','Потому что значений от 1 до n, а людей n'],
 {short:'0 и n − 1 «не дружат».',
 explain:'Число знакомых — от 0 до n − 1 (n вариантов, людей тоже n — пока не хватает). Но если кто-то знаком со <b>всеми</b> (n − 1), то никто не может иметь 0 знакомых. Значит, реально занято не больше n − 1 вариантов, а людей n → двое совпадают.',
 explain2:'Пример для n = 3: значения 0, 1, 2. Если у Ани 2 знакомых (Боря и Вика), то у Бори и Вики хотя бы по одному. Значений «0» и «2» вместе нет — 2 клетки на 3 человека.'}),'r');
G(6,()=>{const n=R(4,6);const E=[];for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)E.push([i,j]);let best=0;
 for(let mask=0;mask<(1<<E.length);mask++){const d=Array(n).fill(0);E.forEach(([i,j],t)=>{if((mask>>t)&1){d[i]++;d[j]++;}});best=Math.max(best,new Set(d).size);}ok(best===n-1,'degrees');
 return {type:'num',q:`В компании ${n} человек. Каждый посчитал, со сколькими из остальных он знаком. Какое наибольшее количество <b>разных</b> чисел может оказаться среди этих ${n} ответов?`,ans:n-1,
 short:`${n-1}: значения 0…${n-1}, но 0 и ${n-1} вместе невозможны.`,
 explain:`Шаг 1. Ответы — от 0 до ${n-1}: ${n} вариантов.<br>Шаг 2. 0 и ${n-1} одновременно невозможны: кто знаком со всеми, тот знаком и с «одиночкой». Значит, разных значений не больше <b>${n-1}</b>.<br>Шаг 3. ${n-1} бывает: компьютер перебрал все ${1<<E.length} вариантов знакомств и нашёл такие (например, когда «самый общительный» знаком со всеми, следующий — со всеми, кроме одного, и т. д.). Поэтому у двоих людей число знакомых <b>всегда</b> совпадает.`,
 explain2:`Это задача про рукопожатия: «докажи, что двое пожали одинаковое число рук». Клеток реально ${n-1}, людей ${n} → по Дирихле двое совпадают, а значит, все ${n} ответов разными быть не могут.`};},'s');
G(6,()=>{const n=R(5,8);let a,blk;do{a=range(1,n).map(()=>R(1,15));const pre=[0];a.forEach(x=>pre.push(pre[pre.length-1]+x));blk=[];for(let i=0;i<n;i++)for(let j=i+1;j<=n;j++)if((pre[j]-pre[i])%n===0)blk.push([i,j]);}while(blk.length!==1||blk[0][1]-blk[0][0]<2||blk[0][1]-blk[0][0]===n);
 const [i0,j0]=blk[0];const fmt=(i,j)=>a.slice(i,j).join(' + ');const right=fmt(i0,j0);const wrong=new Set();let guard=0;
 while(wrong.size<3&&guard++<500){const i=R(0,n-2),j=R(i+2,n);if(!(i===i0&&j===j0))wrong.add(fmt(i,j));}
 const pre=[0];a.forEach(x=>pre.push(pre[pre.length-1]+x));
 return CH(`Даны ${n} чисел подряд: ${a.join(', ')}. Принцип Дирихле обещает: можно выбрать несколько <b>подряд идущих</b>, сумма которых делится на ${n}. Какой это кусок?`,right,[...wrong].slice(0,3),{
 hint:'Посчитай суммы «с начала» и их остатки при делении на '+n+'.',
 short:`${right} = ${pre[j0]-pre[i0]} = ${n} · ${(pre[j0]-pre[i0])/n}.`,
 explain:`Шаг 1. Суммы с начала: ${pre.slice(1).join(', ')}. Остатки при делении на ${n}: ${pre.slice(1).map(x=>x%n).join(', ')}.<br>Шаг 2. ${i0===0?`Остаток 0 у суммы первых ${j0} чисел — она и делится на ${n}.`:`Совпали остатки у ${i0}-й и ${j0}-й сумм (${pre[i0]} и ${pre[j0]}, остаток ${pre[i0]%n}). Их разность — это сумма чисел между ними.`}<br>Шаг 3. ${right} = ${pre[j0]-pre[i0]} — делится на ${n} ✅.<br>Почему так всегда: сумм ${n}; если ни одна не даёт остаток 0, то ${n} сумм в ${n-1} клетках (остатки 1…${n-1}) — две совпадут.`,
 explain2:`Идея «сумм с начала»: сумма куска от (i+1)-го до j-го числа = (сумма первых j) − (сумма первых i). Если остатки у них одинаковые, разность делится на ${n}.`});},'s');
G(6,()=>{const n=R(3,6);const N=2*n;let best=0;for(let mask=1;mask<(1<<N);mask++){const S=[];for(let i=0;i<N;i++)if((mask>>i)&1)S.push(i+1);if(S.length<=best)continue;let good=true;for(let x=0;x<S.length&&good;x++)for(let y=x+1;y<S.length;y++)if(S[y]%S[x]===0){good=false;break;}if(good)best=S.length;}ok(best===n,'antichain');
 const odd=range(1,N).filter(x=>x%2);
 return {type:'num',q:`Из чисел 1, 2, …, ${N} выбирают несколько. Какое наименьшее количество чисел нужно выбрать, чтобы <b>наверняка</b> среди них нашлись два, одно из которых делится на другое?`,ans:n+1,
 hint:'Каждое число = нечётное число · степень двойки. Сколько бывает нечётных частей?',
 short:`Нечётных частей ${n} → ${n+1}. А ${n} чисел ${range(n+1,N).join(', ')} — никто никого не делит.`,
 explain:`Шаг 1 (клетки). Запишем каждое число как (нечётное) · 2<sup>k</sup>: например, ${N} = ${(()=>{let x=N,k=0;while(x%2===0){x/=2;k++;}return `${x} · ${2**k}`;})()}. Нечётных частей от 1 до ${N}: ${odd.join(', ')} — это ${n} клеток.<br>Шаг 2. ${n+1} чисел → два с одной нечётной частью. Они отличаются только степенью двойки, значит, меньшее делит большее.<br>Шаг 3 (пример, что ${n} мало). Числа ${range(n+1,N).join(', ')}: любое частное двух из них меньше 2, поэтому никто никого не делит.<br>Ответ: <b>${n+1}</b>.`,
 explain2:`Компьютер перебрал все наборы из чисел 1…${N}: самый большой набор без пар «делится» имеет ${n} чисел. Значит, ${n+1} — наименьшее количество, при котором пара есть всегда.`};},'s');
G(6,()=>{const N=R(8,14);const S=pick([N+1,N+1,N+2,N,N-1]);const pairs=[];const single=[];for(let a=1;a<=N;a++){const b=S-a;if(b>=1&&b<=N&&b!==a){if(a<b)pairs.push([a,b]);}else single.push(a);}
 const mx=pairs.length+single.length;let bf=0;for(let mask=0;mask<(1<<N);mask++){let c=0,good=true;for(let i=0;i<N&&good;i++)if((mask>>i)&1){c++;const j=S-(i+1)-1;if(j>i&&j<N&&(mask>>j)&1)good=false;}if(good)bf=Math.max(bf,c);}ok(bf===mx,'sum pairs');
 return {type:'num',q:`Из чисел 1, 2, …, ${N} выбирают несколько (разных). Какое наименьшее количество нужно выбрать, чтобы <b>наверняка</b> нашлись два числа с суммой ${S}?`,ans:mx+1,
 short:`Пары с суммой ${S}: ${pairs.length}${single.length?`, без пары: ${single.length}`:''} → ${mx} + 1 = ${mx+1}.`,
 explain:`Шаг 1. Клетки — пары чисел с суммой ${S}: ${pairs.map(p=>`(${p[0]}, ${p[1]})`).join(', ')} — их ${pairs.length}.${single.length?` Числа без пары (${single.join(', ')}) — отдельные клетки по одному числу: ${single.length}.`:''}<br>Шаг 2. Невезение: из каждой пары по одному числу${single.length?' и все одиночки':''} — ${mx} чисел, суммы ${S} нет.<br>Шаг 3. Следующее число попадёт в пару, где уже есть число, — сумма ${S}. Ответ: <b>${mx+1}</b>.`,
 explain2:`Проверь невезение: ${[...pairs.map(p=>p[0]),...single].sort((x,y)=>x-y).join(', ')} — ни одна пара не даёт ${S}. Это ${mx} чисел. Больше без «пары» взять нельзя.`};},'s');

/* L7 ★ */
G(7,()=>CH('Что чаще всего выбирают «клетками» в олимпиадных задачах на делимость?','Остатки при делении на нужное число',['Сами числа','Цифры чисел','Простые делители'],
 {short:'Делимость → остатки.',
 explain:'Если в задаче нужно «делится на n», клетки — <b>остатки при делении на n</b> (их n). Два числа с одним остатком дают разность, кратную n. Это ключ к задачам про 1, 11, 111…, про суммы подряд и многим другим.',
 explain2:'Пример: среди 8 чисел два с разностью, кратной 7, — потому что остатков при делении на 7 только 7.'}),'r');
G(7,()=>{const n=pick([3,7,9,11,13,17,19,21,27,37,41,33,39]);let r=0,k=0;do{r=(r*10+1)%n;k++;}while(r!==0);
 const rem=[];let x=0;for(let i=1;i<=Math.min(k,8);i++){x=(x*10+1)%n;rem.push(x);}
 return {type:'num',q:`Среди чисел 1, 11, 111, 1111, … есть числа, делящиеся на ${n} (это доказывается принципом Дирихле). Из скольких единиц состоит <b>самое маленькое</b> такое число?`,ans:k,
 hint:'Считай остатки по очереди: остаток следующего числа = (остаток предыдущего · 10 + 1) при делении на '+n+'.',
 short:`${'1'.repeat(Math.min(k,12))}${k>12?'…':''} (${k} ${plural(k,'единица','единицы','единиц')}) делится на ${n}.`,
 explain:`Шаг 1. Почему такое число есть: возьмём ${n+1} чисел 1, 11, …; остатков при делении на ${n} — ${n}, у двух остатки совпадут. Их разность = 11…1 00…0 = (число из единиц) · 10<sup>k</sup> делится на ${n}, а с 10 у ${n} нет общих делителей → число из единиц делится на ${n}.<br>Шаг 2. Ищем самое маленькое, считая остатки: ${rem.map((r,i)=>`${'1'.repeat(i+1).length>6?(i+1)+' единиц':'1'.repeat(i+1)} → ${r}`).join('; ')}${k>8?'; …':''}.<br>Шаг 3. Первый раз остаток 0 — у числа из <b>${k}</b> ${plural(k,'единицы','единиц','единиц')}.`,
 explain2:`Хитрость счёта: 111 = 11 · 10 + 1. Поэтому остаток 111 = (остаток 11) · 10 + 1, снова взятое по модулю ${n}. Не надо делить огромные числа! Принцип Дирихле гарантирует, что 0 появится не позже, чем на ${n}-м шаге.`};},'s');
G(7,()=>{const k=pick([10,11,12]);const mx=99*k,mn=10,vals=mx-mn+1,groups=2**k-1;ok(groups>vals,'groups');
 return CH(`Даны ${k} различных двузначных чисел. Почему из них всегда можно выбрать две <b>разные</b> непустые группы с одинаковой суммой?`,`Групп ${groups}, а возможных сумм не больше ${vals} (от ${mn} до ${mx}) — две группы имеют одну сумму`,
 [`Потому что среди ${k} чисел обязательно есть два равных`,`Потому что сумма всех ${k} чисел чётная`,`Потому что групп ${k}, а возможных сумм меньше ${k}`],
 {short:`2<sup>${k}</sup> − 1 = ${groups} > ${vals}.`,
 explain:`Шаг 1. Непустых групп из ${k} чисел: 2<sup>${k}</sup> − 1 = ${groups} (каждое число либо в группе, либо нет; минус пустая группа).<br>Шаг 2. Сумма группы — от ${mn} (одно число 10) до 99 · ${k} = ${mx}: всего не больше ${vals} значений.<br>Шаг 3. ${groups} > ${vals} → по Дирихле две разные группы с одинаковой суммой. Если у них есть общие числа — выкинем их из обеих: суммы останутся равными, а группы станут непересекающимися ✅.<br>«Есть два равных» — неверно: числа по условию различные.`,
 explain2:`Это знаменитая задача Международной математической олимпиады 1972 года (для 10 чисел: 1023 группы и 981 возможная сумма). Кролики — группы, клетки — возможные суммы.`});},'s');
G(7,()=>{const d=pick([1,2,3]);const ans=2**d+1;const W=['на числовой прямой (целые числа)','на клетчатой плоскости (узлы с целыми координатами x, y)','в пространстве (точки с целыми координатами x, y, z)'][d-1];
 return {type:'num',q:`Отмечают точки ${W}. Какое наименьшее число точек нужно отметить, чтобы <b>наверняка</b> у каких-то двух середина отрезка между ними тоже имела целые координаты?`,ans,
 short:`Классов чётности ${2**d} → ${ans}.`,
 explain:`Шаг 1. Середина отрезка: ((x₁ + x₂) : 2${d>1?', (y₁ + y₂) : 2':''}${d>2?', (z₁ + z₂) : 2':''}). Она целая ⇔ каждая сумма координат чётная ⇔ у двух точек <b>одинаковая чётность</b> каждой координаты.<br>Шаг 2. Клетки — наборы чётностей: 2${d>1?' · 2':''}${d>2?' · 2':''} = ${2**d}.<br>Шаг 3. ${2**d} точек мало: ${d===1?'0 и 1':d===2?'(0, 0), (0, 1), (1, 0), (1, 1)':'все 8 вершин кубика с координатами 0 и 1'} — у всех чётности разные. А ${ans} — две в одной клетке. Ответ: <b>${ans}</b>.`,
 explain2:`Почему чётность: (3 + 7) : 2 = 5 — целое (обе нечётные), (3 + 4) : 2 = 3,5 — нет (разная чётность). Для каждой координаты своя «чётность-клетка».`};},'s');

/* ---------- widget ---------- */
function onTheory(root){const w=root.querySelector('#w-rabbits');if(!w)return;
 let cg=[];
 w.innerHTML=`<b>Рассади кроликов по клеткам</b>
 <label>Кроликов: <input type="range" id="rn" min="2" max="30" value="10"><output id="rno"></output></label>
 <label>Клеток: <input type="range" id="rk" min="1" max="8" value="3"><output id="rko"></output></label>
 <div style="font-size:14px;color:var(--muted)">Нажимай на клетку — туда сядет следующий кролик. Попробуй, чтобы в самой полной клетке было как можно меньше!</div>
 <div id="rcg" style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin:10px 0"></div>
 <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" id="rev">Рассадить поровну</button><button class="btn ghost" id="rrnd">Случайно</button><button class="btn ghost" id="rclr">Сначала</button></div>
 <div id="rout" style="margin-top:10px;font-size:16px;line-height:1.55"></div>`;
 const $=id=>w.querySelector('#'+id);
 const reset=()=>{cg=Array(+$('rk').value).fill(0);draw();};
 const draw=()=>{const n=+$('rn').value,k=+$('rk').value;$('rno').textContent=n;$('rko').textContent=k;const placed=cg.reduce((a,b)=>a+b,0),left=n-placed,mx=Math.max(...cg),g=Math.ceil(n/k);
  $('rcg').innerHTML=cg.map((c,i)=>`<button class="btn ghost" data-c="${i}" style="flex-direction:column;min-width:64px;min-height:78px;padding:6px 8px;${left===0&&c===mx?'background:var(--hl);color:var(--ink)':''}"><span style="font-size:22px;font-weight:800">${c}</span><span style="font-size:15px;line-height:1.1">${'🐰'.repeat(Math.min(c,4))}${c>4?'…':''}</span><span style="font-size:11px;color:var(--muted)">клетка ${i+1}</span></button>`).join('');
  w.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>{if(cg.reduce((a,x)=>a+x,0)>=+$('rn').value){$('rout').innerHTML+='<br><b>Все кролики уже рассажены!</b> Нажми «Сначала».';return;}cg[+b.dataset.c]++;draw();});
  $('rout').innerHTML=`Принцип Дирихле обещает: где-то будет не меньше ⌈${n} : ${k}⌉ = <b>${g}</b>.<br>`+(left>0?`Осталось рассадить: <b>${left}</b>. Сейчас в самой полной клетке: ${mx}.`:`Готово! В самой полной клетке <b>${mx}</b>${mx===g?' — ровно столько, сколько обещал Дирихле. Меньше не получится никак! ✅':`. Можно рассадить ровнее — до ${g}. Попробуй!`}`);};
 $('rn').oninput=reset;$('rk').oninput=reset;$('rn').onchange=reset;$('rk').onchange=reset;
 $('rclr').onclick=reset;
 $('rev').onclick=()=>{const n=+$('rn').value,k=+$('rk').value;cg=range(0,k-1).map(i=>Math.floor(n/k)+(i<n%k?1:0));draw();};
 $('rrnd').onclick=()=>{const n=+$('rn').value,k=+$('rk').value;cg=Array(k).fill(0);for(let i=0;i<n;i++)cg[Math.floor(Math.random()*k)]++;draw();};
 reset();}

window.TOPIC={id:'l_dirichlet',title:'Принцип Дирихле',subtitle:'Логика · 5–8 класс',
intro:`<p>Кролики и клетки: как доказать, что совпадение <b>обязательно</b> есть, ничего не зная о деталях. Задачи «сколько взять наверняка», обобщённый принцип ⌈n : k⌉, остатки, геометрия. В конце — рукопожатия, суммы подряд и задачи международных олимпиад.</p>`,
theory,symbols,figs:{},onTheory,
levels:['Кролики и клетки','«Наверняка»: самый невезучий случай','Обобщённый принцип ⌈n : k⌉','Сколько нужно кроликов','Остатки — лучшие клетки','Геометрия и доски','★ Рукопожатия, суммы и делимость','★ Олимпиадные классики'],
gens};
})();
